import{_ as r,o as l,c as o,ae as t}from"./chunks/framework.RRduUuAx.js";const u=JSON.parse('{"title":"常見問題（FAQ）","description":"","frontmatter":{},"headers":[],"relativePath":"v1/zh-HK/faq/index.md","filePath":"v1/zh-HK/faq/index.md"}'),i={name:"v1/zh-HK/faq/index.md"};function e(n,a,s,h,d,g){return l(),o("div",null,[...a[0]||(a[0]=[t('<h1 id="常見問題-faq" tabindex="-1">常見問題（FAQ） <a class="header-anchor" href="#常見問題-faq" aria-label="Permalink to &quot;常見問題（FAQ）&quot;">​</a></h1><p>本頁整理咗用考拉記帳時最常見嘅問題同解決方法。遇到異常情況，建議先喺呢度對照排查。</p><hr><h2 id="帳單匯入" tabindex="-1">帳單匯入 <a class="header-anchor" href="#帳單匯入" aria-label="Permalink to &quot;帳單匯入&quot;">​</a></h2><h3 id="q-支援匯入邊啲帳單來源-各自支援咩檔案格式" tabindex="-1">Q：支援匯入邊啲帳單來源？各自支援咩檔案格式？ <a class="header-anchor" href="#q-支援匯入邊啲帳單來源-各自支援咩檔案格式" aria-label="Permalink to &quot;Q：支援匯入邊啲帳單來源？各自支援咩檔案格式？&quot;">​</a></h3><p><strong>A：</strong> 目前支援 5 種來源：</p><ul><li><strong>模板匯入</strong>：CSV（<code>.csv</code>）</li><li><strong>微信帳單</strong>：CSV / Excel（<code>.csv</code> / <code>.xlsx</code> / <code>.xls</code>）</li><li><strong>支付寶帳單</strong>：CSV（<code>.csv</code>）</li><li><strong>貔貅記帳</strong>：CSV（<code>.csv</code>）</li><li><strong>iCost</strong>：Excel（<code>.xlsx</code> / <code>.xls</code>，不支援 iCost 嘅 CSV）</li></ul><p>可參考相關教學：</p><ul><li><a href="./../guide/01-template-bill-import-guide">模板帳單匯入指南</a></li><li><a href="./../guide/02-wechat-bill-import-guide">微信帳單匯入教學</a></li><li><a href="./../guide/03-alipay-bill-import-guide">支付寶帳單匯入教學</a></li><li><a href="./../guide/07-pixiu-bill-import-guide">貔貅帳單匯入指南</a></li><li><a href="./../guide/08-icost-bill-import-guide">iCost 帳單匯入指南</a></li></ul><h3 id="q-匯入時提示「解析失敗-打開失敗-未搵到表頭」係咩原因" tabindex="-1">Q：匯入時提示「解析失敗／打開失敗／未搵到表頭」係咩原因？ <a class="header-anchor" href="#q-匯入時提示「解析失敗-打開失敗-未搵到表頭」係咩原因" aria-label="Permalink to &quot;Q：匯入時提示「解析失敗／打開失敗／未搵到表頭」係咩原因？&quot;">​</a></h3><p><strong>A：</strong> 多數同以下原因有關（由常見到較少見）：</p><ol><li><strong>匯入來源揀錯</strong>：例如將微信檔當成模板/支付寶去解析，會直接校驗失敗或欄位錯位。</li><li><strong>檔案被二次編輯</strong>：用 Excel/WPS 打開後改咗表頭、刪/加欄位、改分隔符，最易導致解析失敗。</li><li><strong>檔案格式唔支援</strong>：例如 iCost 匯出成 CSV、支付寶匯出為非標準格式等。</li><li><strong>檔案損壞/唔完整</strong>：下載中斷、附件損壞、分享過程遺失內容等。</li><li><strong>檔案太大</strong>：單檔太大可能解析好慢甚至失敗，建議分段匯出再分批匯入。</li></ol><p>建議做法：先由原 App 重新匯出一份「未改動」檔案，並確認考拉記帳入面揀啱匯入來源，再重新解析。</p><h3 id="q-點解匯入後金額變-0-或金額唔啱" tabindex="-1">Q：點解匯入後金額變 0 或金額唔啱？ <a class="header-anchor" href="#q-點解匯入後金額變-0-或金額唔啱" aria-label="Permalink to &quot;Q：點解匯入後金額變 0 或金額唔啱？&quot;">​</a></h3><p><strong>A：</strong> 常見原因：</p><ul><li><strong>收支類型識別錯誤</strong>：部分來源會用「收入/支出」關鍵字決定讀邊一欄金額（例如貔貅嘅流入/流出），類型欄內容異常就可能讀錯。</li><li><strong>金額欄為空或含異常字元</strong>：例如複製貼上帶咗空格、不可見字元。</li><li><strong>千分位/符號</strong>：有啲匯出會帶 <code>+/-</code> 或千分位逗號，一般可兼容；但若二次編輯成特殊格式就可能失敗。</li></ul><p>建議做法：喺預覽頁先核對「收支類型」同「金額」；若有問題，優先重新匯出原檔。</p><h3 id="q-匯入後分類-帳戶-標籤唔匹配點算" tabindex="-1">Q：匯入後分類/帳戶/標籤唔匹配點算？ <a class="header-anchor" href="#q-匯入後分類-帳戶-標籤唔匹配點算" aria-label="Permalink to &quot;Q：匯入後分類/帳戶/標籤唔匹配點算？&quot;">​</a></h3><p><strong>A：</strong> 系統會盡量自動匹配，但唔同 App 嘅分類體系差異大，未必 100% 準確。</p><ul><li><strong>分類唔匹配</strong>：喺預覽頁逐條修正；或者先喺考拉記帳建立同匯出檔同名分類，再重新解析會更易匹配。</li><li><strong>帳戶唔匹配</strong>：多數按帳戶名/支付方式匹配；搵唔到時可能會自動建立新帳戶。建議先建立常用帳戶，再喺預覽頁統一修正。</li><li><strong>標籤唔匹配</strong>：按標籤名匹配；不存在嘅標籤可能會被建立。留意有無出現多餘空格/符號導致嘅「怪標籤」。</li></ul><h3 id="q-匯入會自動去重嗎-重複匯入會點" tabindex="-1">Q：匯入會自動去重嗎？重複匯入會點？ <a class="header-anchor" href="#q-匯入會自動去重嗎-重複匯入會點" aria-label="Permalink to &quot;Q：匯入會自動去重嗎？重複匯入會點？&quot;">​</a></h3><p><strong>A：</strong> 唔同來源策略唔同，但整體建議當成「唔會自動去重」去用。</p><ul><li><strong>最穩陣做法</strong>：避免重複匯入同一檔/同一時間段；分批匯入時確保時間範圍唔重疊。</li><li><strong>已經重複咗</strong>：可喺帳單列表按時間段篩選後手動刪除重複記錄。</li></ul><h3 id="q-退款-轉帳-紅包等特殊記錄匯入後點睇" tabindex="-1">Q：退款/轉帳/紅包等特殊記錄匯入後點睇？ <a class="header-anchor" href="#q-退款-轉帳-紅包等特殊記錄匯入後點睇" aria-label="Permalink to &quot;Q：退款/轉帳/紅包等特殊記錄匯入後點睇？&quot;">​</a></h3><p><strong>A：</strong> 呢類記錄喺唔同平台匯出欄位差異好大，匯入後建議：</p><ul><li>喺預覽頁重點檢查「收支類型」同「金額正負」</li><li>有需要就手動調整分類（例如將「退款」歸到「退款/其他收入」）</li><li>備註通常會拼接交易狀態/交易單號等資料，方便你回溯來源</li></ul><h3 id="q-一次匯入幾多比較好-匯入好慢點算" tabindex="-1">Q：一次匯入幾多比較好？匯入好慢點算？ <a class="header-anchor" href="#q-一次匯入幾多比較好-匯入好慢點算" aria-label="Permalink to &quot;Q：一次匯入幾多比較好？匯入好慢點算？&quot;">​</a></h3><p><strong>A：</strong> 建議按「時間範圍」拆分：</p><ul><li>微信/支付寶建議每次匯出唔超過 <strong>3 個月</strong>，檔案更穩定、解析更快</li><li>資料量好大就分多次匯出，多次匯入</li><li>匯入期間建議保持 App 喺前台，避免系統回收導致中斷</li></ul><hr><h2 id="多帳本" tabindex="-1">多帳本 <a class="header-anchor" href="#多帳本" aria-label="Permalink to &quot;多帳本&quot;">​</a></h2><h3 id="q-切換帳本後資料「唔見咗」" tabindex="-1">Q：切換帳本後資料「唔見咗」？ <a class="header-anchor" href="#q-切換帳本後資料「唔見咗」" aria-label="Permalink to &quot;Q：切換帳本後資料「唔見咗」？&quot;">​</a></h3><p><strong>A：</strong> 多數係切咗去另一個帳本。帳單、分類、標籤、統計都係「帳本隔離」。</p><p>建議做法：返去「帳本管理」確認而家選中嘅帳本，再睇返帳單列表。</p><h3 id="q-邊啲資料係帳本隔離-邊啲係共用" tabindex="-1">Q：邊啲資料係帳本隔離？邊啲係共用？ <a class="header-anchor" href="#q-邊啲資料係帳本隔離-邊啲係共用" aria-label="Permalink to &quot;Q：邊啲資料係帳本隔離？邊啲係共用？&quot;">​</a></h3><p><strong>A：</strong></p><ul><li><strong>帳本隔離</strong>：帳單、分類、標籤、統計等</li><li><strong>裝置共用</strong>：帳戶（同一部機上多個帳本可共用同一個帳戶）</li></ul><h3 id="q-刪除帳本會點-可唔可以復原" tabindex="-1">Q：刪除帳本會點？可唔可以復原？ <a class="header-anchor" href="#q-刪除帳本會點-可唔可以復原" aria-label="Permalink to &quot;Q：刪除帳本會點？可唔可以復原？&quot;">​</a></h3><p><strong>A：</strong> 刪除後，該帳本資料會由本機移除；如你已開啟雲端同步，後續同步亦會喺雲端刪除。App 內無法復原，刪之前請先確認並做好備份。</p><hr><h2 id="貨幣與匯率" tabindex="-1">貨幣與匯率 <a class="header-anchor" href="#貨幣與匯率" aria-label="Permalink to &quot;貨幣與匯率&quot;">​</a></h2><h3 id="q-本位幣-帳本貨幣係咩-會影響邊啲地方" tabindex="-1">Q：本位幣/帳本貨幣係咩？會影響邊啲地方？ <a class="header-anchor" href="#q-本位幣-帳本貨幣係咩-會影響邊啲地方" aria-label="Permalink to &quot;Q：本位幣/帳本貨幣係咩？會影響邊啲地方？&quot;">​</a></h3><p><strong>A：</strong> 本位幣（帳本貨幣）係當前帳本嘅「主要顯示貨幣」，會影響：</p><ul><li>金額顯示（會做換算顯示）</li><li>概覽與統計嘅計算口徑</li><li>匯率列表以本位幣作基準</li></ul><h3 id="q-點解刷新匯率後-歷史帳單嘅換算顯示變咗" tabindex="-1">Q：點解刷新匯率後，歷史帳單嘅換算顯示變咗？ <a class="header-anchor" href="#q-點解刷新匯率後-歷史帳單嘅換算顯示變咗" aria-label="Permalink to &quot;Q：點解刷新匯率後，歷史帳單嘅換算顯示變咗？&quot;">​</a></h3><p><strong>A：</strong> 換算顯示用嘅係「目前匯率」。當你刷新匯率或切換本位幣後，歷史帳單嘅<strong>換算顯示</strong>可能會變，但<strong>原始交易金額</strong>唔會改變。</p><h3 id="q-離線時匯率點處理-刷新失敗點算" tabindex="-1">Q：離線時匯率點處理？刷新失敗點算？ <a class="header-anchor" href="#q-離線時匯率點處理-刷新失敗點算" aria-label="Permalink to &quot;Q：離線時匯率點處理？刷新失敗點算？&quot;">​</a></h3><p><strong>A：</strong> 離線時會盡量用已保存嘅匯率資料。刷新失敗建議：</p><ol><li>檢查網絡</li><li>遲啲再試刷新</li><li>若你手動改過匯率，確認數值係咪符合預期</li></ol><hr><h2 id="雲端備份與同步" tabindex="-1">雲端備份與同步 <a class="header-anchor" href="#雲端備份與同步" aria-label="Permalink to &quot;雲端備份與同步&quot;">​</a></h2><h3 id="q-雲端備份需要登入嗎-支援咩登入方式" tabindex="-1">Q：雲端備份需要登入嗎？支援咩登入方式？ <a class="header-anchor" href="#q-雲端備份需要登入嗎-支援咩登入方式" aria-label="Permalink to &quot;Q：雲端備份需要登入嗎？支援咩登入方式？&quot;">​</a></h3><p><strong>A：</strong> 需要登入。目前支援 Apple 登入；入口喺「設定」頁面頂部嘅使用者卡片。</p><h3 id="q-邊啲資料會同步-邊啲唔會" tabindex="-1">Q：邊啲資料會同步？邊啲唔會？ <a class="header-anchor" href="#q-邊啲資料會同步-邊啲唔會" aria-label="Permalink to &quot;Q：邊啲資料會同步？邊啲唔會？&quot;">​</a></h3><p><strong>A：</strong></p><ul><li><strong>會同步</strong>：帳本、帳單、帳戶、分類、標籤</li><li><strong>唔會同步</strong>：App 本地設定（主題/語言等）、快取、偏好設定</li></ul><h3 id="q-幾時會自動同步-點手動同步" tabindex="-1">Q：幾時會自動同步？點手動同步？ <a class="header-anchor" href="#q-幾時會自動同步-點手動同步" aria-label="Permalink to &quot;Q：幾時會自動同步？點手動同步？&quot;">​</a></h3><p><strong>A：</strong></p><ul><li><strong>自動同步</strong>：通常喺 App 啟動、資料變更後、切換帳本時觸發</li><li><strong>手動同步</strong>：喺「設定」頁右上角點雲朵圖示</li></ul><p>手動同步期間建議保持 App 喺前台直到完成。</p><h3 id="q-多部機同時改同一條資料會點" tabindex="-1">Q：多部機同時改同一條資料會點？ <a class="header-anchor" href="#q-多部機同時改同一條資料會點" aria-label="Permalink to &quot;Q：多部機同時改同一條資料會點？&quot;">​</a></h3><p><strong>A：</strong> 系統會盡量保留最新修改，同時避免「尚未同步嘅本機修改」被雲端覆蓋。多裝置同時用嘅情況下，建議先等其中一部機同步完成，再喺另一部機做大量編輯。</p><h3 id="q-卸載-換機後資料可唔可以復原" tabindex="-1">Q：卸載/換機後資料可唔可以復原？ <a class="header-anchor" href="#q-卸載-換機後資料可唔可以復原" aria-label="Permalink to &quot;Q：卸載/換機後資料可唔可以復原？&quot;">​</a></h3><p><strong>A：</strong></p><ul><li><strong>已登入並完成同步</strong>：重新安裝後登入同一帳號，等同步完成即可復原</li><li><strong>未登入</strong>：資料只喺本機，卸載後無法復原</li></ul><hr><h2 id="會員與定價" tabindex="-1">會員與定價 <a class="header-anchor" href="#會員與定價" aria-label="Permalink to &quot;會員與定價&quot;">​</a></h2><h3 id="q-點解會員唔採用一次性買斷" tabindex="-1">Q：點解會員唔採用一次性買斷？ <a class="header-anchor" href="#q-點解會員唔採用一次性買斷" aria-label="Permalink to &quot;Q：點解會員唔採用一次性買斷？&quot;">​</a></h3><p><strong>A：</strong> 因為我希望將考拉記帳做成一個長期持續優化嘅產品，而唔係「一槌子買賣」。</p><p>會員制可以令我有動力長期投入：持續修 bug、打磨體驗、跟進系統更新同新機型適配，亦會長期投入同步、資料安全、效能等需要持續迭代嘅能力建設。咁你用到嘅會係愈用愈好嘅 App，而唔係買斷後更新動力不足、維護不可持續嘅風險。</p><hr><h2 id="回饋與支援" tabindex="-1">回饋與支援 <a class="header-anchor" href="#回饋與支援" aria-label="Permalink to &quot;回饋與支援&quot;">​</a></h2><h3 id="q-回報問題時提供咩資料會更快解決" tabindex="-1">Q：回報問題時提供咩資料會更快解決？ <a class="header-anchor" href="#q-回報問題時提供咩資料會更快解決" aria-label="Permalink to &quot;Q：回報問題時提供咩資料會更快解決？&quot;">​</a></h3><p><strong>A：</strong> 建議一併提供（越完整越易定位）：</p><ul><li>你用嘅匯入來源（微信/支付寶/貔貅/iCost/模板）</li><li>檔案格式（CSV/Excel）同匯出時間範圍</li><li>報錯提示截圖（如有）</li><li>你已嘗試過嘅方法（重新匯出/改來源/換檔案等）</li></ul>',75)])])}const c=r(i,[["render",e]]);export{u as __pageData,c as default};
